import { path } from '@servicenow/sdk-build-core'
import { findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from './test-utils'
import { createTestContext } from '../../test-utils'

describe('Flow Trigger Instance Plugin Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    // -----------------------------------------------------------------------------
    // Flow Trigger Instance Plugin Tests
    // Tests for handling empty trigger inputs
    // -----------------------------------------------------------------------------
    describe('Empty Inputs in the Trigger instance', () => {
        test('Knowledge Management trigger with no inputs returns empty array', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'knowledge-management-trigger.now.ts',
                'oob-triggers/fluent'
            )

            // Verify trigger instance was created
            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const triggerInstance = merged['sys_hub_trigger_instance_v2'][0]
            expect(triggerInstance).toBeDefined()
            expect(triggerInstance.trigger_inputs).toBeDefined()

            // Decode and verify empty inputs array
            const triggerInputs = unzipInputArray(triggerInstance.trigger_inputs)
            expect(Array.isArray(triggerInputs)).toBe(true)
            expect(triggerInputs).toHaveLength(0)
        })

        test('SLA Task trigger with empty inputs returns empty array', async () => {
            const project = ctx.createProject()

            // Use XML transformation since the Fluent file has diagnostic errors
            const xmlContent = loadTestFile('Test_SLA_Task_Trigger_Advanced.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_SLA_Task_Trigger_Advanced.xml',
                content: xmlContent,
            })

            // Verify transformation succeeded
            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify it's an SLA Task trigger
            expect(content).toContain('trigger.application.slaTask')

            // SLA Task trigger has no inputs (empty object {})
            // The regex allows for multiline formatting with newlines and indentation
            expect(content).toMatch(/wfa\.trigger\(\s*trigger\.application\.slaTask\s*,\s*\{[^}]*\}\s*,\s*\{\s*\}/s)
        })
    })

    describe('Inbound Email Trigger', () => {
        test('Inbound Email trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'inbound-email-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('email_conditions')).toBe('subjectLIKEtest')
            expect(val('target_table')).toBe('incident')
        })
    })

    describe('Remote Table Query Trigger', () => {
        test('Remote Table Query trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'remote-table-query-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('u_table')).toBe('sc_cat_item')
        })
    })

    describe('Service Catalog Trigger', () => {
        test('Service Catalog trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'service-catalog-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Get the first flow (testServiceCatalogTrigger)
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('run_flow_in')).toBe('background')
        })

        test('Service Catalog trigger with foreground execution', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'service-catalog-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Get the second flow (testServiceCatalogTriggerForeground)
            const trgInst = merged['sys_hub_trigger_instance_v2'][1]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('run_flow_in')).toBe('foreground')
        })
    })

    // =============================================================================
    // Bi-Directional Tests: Fluent → XML → Fluent
    // =============================================================================

    describe('Application Triggers - Fluent to XML', () => {
        test('Knowledge Management trigger with empty inputs generates correct XML', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'knowledge-management-trigger.now.ts',
                'oob-triggers/fluent'
            )

            // Verify trigger instance was created
            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst).toBeDefined()
            expect(trgInst.trigger_type).toBe('knowledge_management')

            // Verify empty inputs
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            expect(Array.isArray(inputsArr)).toBe(true)
            expect(inputsArr).toHaveLength(0)
        })

        test('Inbound Email trigger generates correct XML with all parameters', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'inbound-email-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('email')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify input parameters are in XML
            expect(val('email_conditions')).toBe('subjectLIKEtest')
            expect(val('target_table')).toBe('incident')
            expect(val('order')).toBe(100)
            expect(val('stop_condition_evaluation')).toBe(true)
        })

        test('Remote Table Query trigger generates correct XML with u_table parameter', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'remote-table-query-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('remote_table_query')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify u_table parameter is in XML
            expect(val('u_table')).toBe('sc_cat_item')
        })

        test('SLA Task trigger generates correct XML with empty inputs', async () => {
            const project = ctx.createProject()

            // Use XML transformation since the Fluent file has diagnostic errors
            const xmlContent = loadTestFile('Test_SLA_Task_Trigger_Advanced.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_SLA_Task_Trigger_Advanced.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify it's an SLA Task trigger with empty inputs
            expect(content).toContain('trigger.application.slaTask')
            expect(content).toContain('wfa.trigger')

            // SLA Task trigger has no inputs (empty object {})
            // The regex allows for multiline formatting with newlines and indentation
            expect(content).toMatch(/wfa\.trigger\(\s*trigger\.application\.slaTask\s*,\s*\{[^}]*\}\s*,\s*\{\s*\}/s)
        })
    })

    describe('Application Triggers - XML to Fluent', () => {
        test('Knowledge Management XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Knowledge_Management_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Knowledge_Management_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.application.knowledgeManagement')
            expect(content).toContain('Flow(')
            expect(content).toContain('wfa.trigger(')

            // Verify empty inputs (Knowledge Management has no inputs)
            expect(content).toMatch(
                /wfa\.trigger\(\s*trigger\.application\.knowledgeManagement\s*,\s*\{[^}]*\}\s*,\s*\{\s*\}/s
            )
        })

        test('Inbound Email XML transforms to correct Fluent code with parameters', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'inbound-email-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('email')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify trigger parameters with precise values
            expect(val('email_conditions')).toBe('subjectLIKEtest')
            expect(val('target_table')).toBe('incident')
            expect(val('order')).toBe(100)
            expect(val('stop_condition_evaluation')).toBe(true)
        })

        test('Remote Table Query XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(
                project,
                'remote-table-query-trigger.now.ts',
                'oob-triggers/fluent'
            )

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('remote_table_query')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify trigger parameters with precise values
            expect(val('u_table')).toBe('sc_cat_item')
        })

        test('Generated Fluent code has correct trigger outputs usage', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_InboundEmail_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_InboundEmail_Trigger.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify trigger outputs are accessible via params
            expect(content).toContain('params.trigger')
            expect(content).toContain('params.trigger.from_address')
            expect(content).toContain('params.trigger.subject')
            expect(content).toContain('params.trigger.inbound_email')
            expect(content).toContain('params.trigger.target_table_name')
            expect(content).toContain('params.trigger.target_record')

            // Verify correct data types are used for data pills
            expect(content).toContain("wfa.dataPill(_params.trigger.from_address, 'string_full_utf8')")
            expect(content).toContain("wfa.dataPill(_params.trigger.subject, 'string_full_utf8')")
            expect(content).toContain("wfa.dataPill(_params.trigger.inbound_email, 'reference')")
            expect(content).toContain("wfa.dataPill(_params.trigger.target_table_name, 'table_name')")
            expect(content).toContain("wfa.dataPill(_params.trigger.target_record, 'reference')")

            // Verify action exists
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.core.log')
        })

        test('Remote Table Query trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Remote_Query_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Remote_Query_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            expect(changedFiles[0].getName()).toBe('Test_Remote_Query_Trigger.now.ts')

            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.application.remoteTableQuery')
            expect(content).toContain('wfa.trigger(')

            // Verify trigger parameters
            expect(content).toMatch(/u_table:|table:/)

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger')
        })

        test('Service Catalog trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Service_Catalog_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Service_Catalog_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            expect(changedFiles[0].getName()).toBe('Test_Service_Catalog_Trigger.now.ts')

            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.application.serviceCatalog')
            expect(content).toContain('wfa.trigger(')

            // Verify trigger parameters
            expect(content).toContain('run_flow_in:')

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger')
        })

        test('SLA Task trigger Fluent code uses all trigger outputs including sla_flow_inputs', async () => {
            // Read the existing SLA task trigger Fluent file
            const fluentContent = loadTestFile('sla-task-trigger.now.ts', 'oob-triggers/fluent')

            // Verify trigger outputs are used in the Fluent file
            expect(fluentContent).toContain('_params.trigger.task_sla_record')
            expect(fluentContent).toContain('_params.trigger.sla_flow_inputs')
            expect(fluentContent).toContain('_params.trigger.sla_flow_inputs.name')
            expect(fluentContent).toContain('_params.trigger.sla_flow_inputs.duration')
            expect(fluentContent).toContain('_params.trigger.sla_flow_inputs.duration_type')

            // Verify correct data types are used for data pills
            expect(fluentContent).toContain("wfa.dataPill(_params.trigger.task_sla_record, 'records')")
            expect(fluentContent).toContain("wfa.dataPill(_params.trigger.sla_flow_inputs.name, 'string')")
            expect(fluentContent).toContain("wfa.dataPill(_params.trigger.sla_flow_inputs.duration, 'string')")
            expect(fluentContent).toContain("wfa.dataPill(_params.trigger.sla_flow_inputs.duration_type, 'string')")
        })

        test('DEF0777644: SLA Task trigger XML transforms with nested data pills', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('DEF0777644_SLA_Invalid_Inputs.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'DEF0777644_SLA_Invalid_Inputs.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger.task_sla_record')
            expect(content).toContain('_params.trigger.sla_flow_inputs')
            expect(content).toContain('_params.trigger.task_sla_record.sla')
            expect(content).toContain('_params.trigger.task_sla_record.sla.duration')

            // Verify correct data types are used for data pills
            expect(content).toContain("wfa.dataPill(_params.trigger.task_sla_record, 'reference')")
            expect(content).toContain("wfa.dataPill(_params.trigger.task_sla_record.sla, 'reference')")
            expect(content).toContain("wfa.dataPill(_params.trigger.task_sla_record.sla.duration, 'glide_duration')")
            expect(content).toContain("wfa.dataPill(_params.trigger.sla_flow_inputs, 'object')")
        })
    })

    describe('Application Triggers - Round Trip', () => {
        test('Knowledge Management: Fluent → XML → Fluent preserves trigger configuration', async () => {
            const project1 = ctx.createProject()

            // Fluent → XML
            const merged = await getMergedRecordUpdates(
                project1,
                'knowledge-management-trigger.now.ts',
                'oob-triggers/fluent'
            )

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('knowledge_management')

            // Verify empty inputs are preserved
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            expect(inputsArr).toHaveLength(0)
        })

        test('Inbound Email: Fluent → XML preserves all input parameters', async () => {
            const project = ctx.createProject()

            const merged = await getMergedRecordUpdates(project, 'inbound-email-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify parameters are preserved
            expect(val('email_conditions')).toBeDefined()
            expect(val('target_table')).toBeDefined()

            // Verify values are correct
            expect(val('email_conditions')).toBe('subjectLIKEtest')
            expect(val('target_table')).toBe('incident')
        })
    })
})
